import sys

def main():
    import sys
    input = sys.stdin.read().split()
    N, M = int(input[0]), int(input[1])
    first_map = input[2:2+N]
    second_map = input[2+N:]

    for i in range(N - M + 1):
        for j in range(N - M + 1):
            match = True
            for k in range(M):
                if first_map[i+k][j:j+M] != second_map[k][j:j+M]:
                    match = False
                    break
            if match:
                print(i + 1, j + 1)
                return

main()
